extra_head_css:
.text-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .text-sidebar { flex: 0 0 300px; display: flex; flex-direction: column; gap: 14px; }
    .text-canvas-area { flex: 1; min-width: 300px; }

    .control-group { display: flex; flex-direction: column; gap: 6px; }
    .control-group label { font-size: .8rem; color: var(--text-secondary); font-weight: 500; }
    .control-group select, .control-group input[type="number"], .control-group textarea {
      padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }
    .control-group textarea { resize: vertical; min-height: 60px; font-family: inherit; }
    .control-group input[type="range"] { width: 100%; }
    .control-group input[type="color"] {
      width: 100%; height: 36px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); cursor: pointer; padding: 2px;
    }

    .color-row { display: flex; gap: 8px; }
    .color-row .control-group { flex: 1; }

    .position-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
    .pos-btn {
      padding: 6px 4px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      text-align: center; font-size: .75rem; transition: all .2s;
    }
    .pos-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .pos-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }

    .canvas-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 300px;
      overflow: auto; position: relative; user-select: none;
    }
    .canvas-wrapper canvas { max-width: 100%; max-height: 500px; border-radius: 4px; cursor: move; }

    @media (max-width: 768px) {
      .text-workspace { flex-direction: column; }
      .text-sidebar { flex: none; width: 100%; }
    }
